using System.Text.Json.Nodes;
using IdiotProof.Operations.Rendering;
using IdiotProof.Scripting;

namespace IdiotProof.Operations.Dsl;

public sealed record DslSchemaArgs
{
    [Argument(0, Name = "object", Description = "Only one object of the schema: strategy, step, condition, takeProfitTarget, conditionalBlock, branch, overrides, or a condition type such as indicatorCondition; omit for the whole schema.", Required = false, Example = "indicatorCondition")]
    public string? Object { get; init; }
}

/// <summary>
/// The JSON Schema of the canonical strategy JSON (IP-LAW-8), generated by
/// <see cref="StrategyJson.Schema"/> from the allow-lists the strict reader itself checks keys
/// against (IP-T526). The reader stays the authority: the schema lists exactly the keys the reader
/// accepts and is no looser than it on types, nulls and required keys. <c>--json</c> returns the
/// schema; the text form is a key table per object.
/// </summary>
[Operation("dsl schema", Summary = "The JSON Schema of the canonical strategy JSON, generated from the strict reader's own key tables (IP-LAW-4).", Risk = OperationRisk.Read)]
[Example("idiotproof dsl schema")]
[Example("idiotproof dsl schema --json", Description = "The schema itself (draft 2020-12).")]
[Example("idiotproof dsl schema indicatorCondition", Description = "One object: its keys, types and which are required.")]
public sealed class DslSchemaOperation : IOperation<DslSchemaArgs>
{
    public Task<OperationResult> ExecuteAsync(DslSchemaArgs args, OperationContext ctx)
    {
        var schema = StrategyJson.Schema();
        var defs = schema["$defs"]!.AsObject();
        var objects = new List<(string Name, JsonObject Schema)> { ("strategy", schema) };
        objects.AddRange(defs.Select(d => (d.Key, d.Value!.AsObject())));

        if (!string.IsNullOrWhiteSpace(args.Object))
        {
            var wanted = args.Object.Trim();
            var match = objects.Where(o => o.Name.Equals(wanted, StringComparison.OrdinalIgnoreCase)).ToList();
            if (match.Count == 0)
                return Task.FromResult(OperationResult.Usage($"No schema object '{wanted}'. Objects: {string.Join(", ", objects.Select(o => o.Name))}."));
            var one = match[0];
            // One object on its own still needs the definitions its $refs point at.
            var data = one.Name == "strategy" ? schema : new JsonObject
            {
                ["$schema"] = StrategyJson.SchemaDialect,
                ["$ref"] = "#/$defs/" + one.Name,
                ["$defs"] = defs.DeepClone(),
            };
            return Task.FromResult(OperationResult.Ok(data, Render(one.Name, one.Schema, ctx.Width)));
        }

        var human = string.Join("\n\n", objects.Select(o => Render(o.Name, o.Schema, ctx.Width)))
            + $"\n\n{schema["title"]}. Generated from the strict reader's key tables; `--json` returns the JSON Schema.";
        return Task.FromResult(OperationResult.Ok(schema, human));
    }

    private static string Render(string name, JsonObject schema, int? width)
    {
        var head = name + (schema["description"] is { } d ? " — " + d.GetValue<string>() : "");
        if (schema["oneOf"] is JsonArray oneOf)
            return head + "\n  one of: " + string.Join(", ", oneOf.Select(o => o!["$ref"]!.GetValue<string>().Split('/')[^1]));
        var required = (schema["required"] as JsonArray)?.Select(r => r!.GetValue<string>()).ToHashSet() ?? [];
        var table = new TextTable { MaxWidth = width }.Column("Key").Column("Value").Column("Required").Column("Meaning");
        foreach (var (key, value) in schema["properties"]!.AsObject())
            table.Row(key, Describe(value!.AsObject()), required.Contains(key) ? "yes" : "", value!["description"]?.GetValue<string>() ?? "");
        return head + "\n" + table.Render();
    }

    /// <summary>A key's value schema in a few words: <c>number|null</c>, <c>Long|Short|null</c>, <c>condition[]</c>.</summary>
    internal static string Describe(JsonObject value)
    {
        if (value["const"] is { } constant) return constant.ToJsonString();
        if (value["enum"] is JsonArray names) return string.Join("|", names.Select(n => n is null ? "null" : n.ToJsonString().Trim('"')));
        if (value["$ref"] is { } reference) return reference.GetValue<string>().Split('/')[^1];
        if (value["anyOf"] is JsonArray any) return string.Join("|", any.Select(a => Describe(a!.AsObject())));
        var type = value["type"] switch
        {
            JsonArray types => string.Join("|", types.Select(t => t!.GetValue<string>())),
            { } single => single.GetValue<string>(),
            _ => "any",
        };
        if (type == "array" && value["items"] is JsonObject items) return Describe(items) + "[]";
        if (value["pattern"] is { } pattern && pattern.GetValue<string>().Contains(':')) type = type.Replace("string", "HH:mm[:ss]");
        return type;
    }
}
